        'border:1px solid ' + (actif ? 'var(--button-color,#FFB840)' : 'transparent') + ';' + (actif ? 'background:rgba(127,127,127,.22);' : '') + (impossible ? 'opacity:.4;cursor:default;' : '');
      const t = document.createElement('span');
