  function fondAutourListe(cadre) {
    for (let el = cadre && cadre.parentElement; el && el !== document.documentElement; el = el.parentElement) {
      const c = getComputedStyle(el).backgroundColor;
      const m = c.match(/rgba?\(([^)]+)\)/);
      if (!m) continue;
      const v = m[1].split(/[\s,\/]+/).filter(Boolean);
      if (v.length < 4 || parseFloat(v[3]) > 0.5) return c;
    }
    return '';
  }

