        url: url,
        responseType: 'arraybuffer',
        onload: function (r) {
          if (r.status >= 200 && r.status < 300 && r.response) ok(r.response);
          else echec(new Error('Téléchargement impossible (HTTP ' + r.status + ')'));
        },
        onerror: function () { echec(new Error('Téléchargement impossible')); },
        ontimeout: function () { echec(new Error('Téléchargement trop long')); },
