  function concerneToast(node) {
    if (node.nodeType === 3) node = node.parentElement;
    if (!node || node.nodeType !== 1) return null;
    if (node.classList.contains('toast') || node.classList.contains('toast-container')) return node;
    const t = node.closest('.toast-container, .toast');
    if (t) return t;
    return node.getElementsByClassName('toast').length || node.getElementsByClassName('toast-container').length ? node : null;
  }
  function surAjoutNoeudsNotif(mutations) {
    const vus = new Set();
    for (let i = 0; i < mutations.length; i++) {
      const ajouts = mutations[i].addedNodes;
      for (let j = 0; j < ajouts.length; j++) {
        const n = concerneToast(ajouts[j]);
        if (n) vus.add(n);
      }
    }
    vus.forEach(function (node) {
      verifierNoeudEtEnfants(node);

      setTimeout(function () { verifierNoeudEtEnfants(node); }, 60);
    });
  }

