    sep(1);
    [1, 2, 3, 4].forEach(function (c) {
      bouton(NOMS[c], 'code' + c, LONGS[c] + (c === 4 ? ' : taille réelle, sans dépasser le post' : ' : ' + Math.round(GAB_POURCENTS[c] * 100) + ' % de la largeur du post (plus grand côté)'));
    });
