    icone(bouton('', 'galerie', 'Ouvrir la galerie (images et vidéos de la page)'), '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 16 5-5 4 4 3-3 6 6"/><circle cx="16" cy="9" r="1.3"/>');
