      '-webkit-mask:' + MASQUE_POINTS + ' center/contain no-repeat;mask:' + MASQUE_POINTS + ' center/contain no-repeat}' +
    '[data-mp-poignee][data-mp-survol]{opacity:.65}' +
    '[data-mp-poignee]:hover,[data-mp-poignee][data-mp-tire]{opacity:1;background:var(--line-color,var(--button-text-color,#C5C8C6))}' +
    '@media (hover:none){[data-mp-poignee]{opacity:.6}}' +

    '[data-mp-fenetre]{display:flex!important;flex-direction:column!important;gap:8px!important;padding:0 8px 0!important}' +
    '[data-mp-fenetre] > [data-mp-entete]{order:-1;margin:0 -8px!important;flex:none}' +
    '[data-mp-fenetre] > *{margin-top:0!important;margin-bottom:0!important;flex-shrink:0!important}' +
    '[data-mp-fenetre] > [data-mp-boutons]{order:5;position:sticky;bottom:0;z-index:4;margin-top:auto!important;padding:6px 0 12px!important;' +
      'background:var(--nana-background-color,#1a1c1e);display:flex;gap:8px;justify-content:center}' +
    '[data-mp-fenetre] > [data-mp-boutons] button{height:34px!important;min-height:0!important;padding-top:0!important;padding-bottom:0!important;margin-top:0!important;margin-bottom:0!important}' +
    '[data-mp-fenetre] [data-mp-titre-apercu]{margin:0 0 6px!important;font-size:inherit}' +
    '[data-mp-fenetre] .preview-box{margin-bottom:0!important}' +

    '[data-mp-fenetre]:not(:has(> [data-mp-boutons])){padding-bottom:18px!important}';
  document.head.appendChild(styleAuto);

  function finitionFenetre(f, deja) {
    if (!f || !(flottant || deja)) return;
    f.setAttribute('data-mp-fenetre', '');
    const rangee = Array.from(f.children).find(function (c) {
      return !c.hasAttribute('data-mp-entete') && Array.from(c.querySelectorAll ? c.querySelectorAll('button') : []).concat(c.tagName === 'BUTTON' ? [c] : [])
        .some(function (b) { return /^(Poster|Publier|Confirmer|Annuler|Envoyer)$/i.test(b.textContent.trim()); }) && !c.querySelector('textarea');
    });
    Array.from(f.querySelectorAll('[data-mp-boutons]')).forEach(function (c) { if (c !== rangee) c.removeAttribute('data-mp-boutons'); });
    if (rangee && !rangee.hasAttribute('data-mp-boutons')) rangee.setAttribute('data-mp-boutons', '');
    f.querySelectorAll('h1,h2,h3,h4,div,span,p,label').forEach(function (el) {
      const t = el.firstChild;
      if (!t || t.nodeType !== 3 || !/^\s*Aperçu du message\s*:?\s*$/.test(t.data)) return;
      el.setAttribute('data-mp-titre-apercu', '');
      if (/:\s*$/.test(t.data)) t.data = t.data.replace(/\s*:\s*$/, ' ');
    });
  }

  const CLASSE_APPUI = 'nanachan-pastille-appui';
  const styleAppui = document.createElement('style');
  styleAppui.textContent =
    '.' + CLASSE_APPUI + '{opacity:1!important;transition:none!important;background:var(--button-color,#373B41)!important;}';
  document.head.appendChild(styleAppui);

  function zoneReponse() {
    return Array.from(document.querySelectorAll('textarea')).find(function (z) {
      return !z.closest('.post-container[id^="post-"]');
    }) || null;
  }

  function zoneEdition() {
    return Array.from(document.querySelectorAll('.post-container[id^="post-"] textarea')).find(function (z) {
      return !!blocEdition(z);
    }) || null;
  }
  function trouverZoneTexte() {
    const ze = zoneEdition();
    if (ze) return ze;
    if (flottant && formulaireFlottant && formulaireFlottant.isConnected) {
      const z = formulaireFlottant.querySelector('textarea');
      if (z) return z;
    }
    return zoneReponse();
  }

  function editionEnCours() {
    return !!document.querySelector('.post-container[id^="post-"] textarea');
  }
  let bulleEdition = null;
  function signalerEdition() {
    if (!bulleEdition) {
      bulleEdition = document.createElement('div');
      bulleEdition.style.cssText = 'position:fixed;right:70px;bottom:24px;z-index:9999;padding:8px 12px;border-radius:6px;font-size:13px;' +
        'background:var(--button-color,#373B41);color:var(--button-text-color,#C5C8C6);box-shadow:0 4px 14px rgba(0,0,0,.45);pointer-events:none;' +
        'transition:opacity .2s ease;';
      bulleEdition.textContent = 'Termine (ou annule) l\'édition du post avant d\'ouvrir Messages+.';
      document.body.appendChild(bulleEdition);
    }
    bulleEdition.style.opacity = '1';
    clearTimeout(bulleEdition._minuteur);
    bulleEdition._minuteur = setTimeout(function () { bulleEdition.style.opacity = '0'; }, 2500);
  }

  function trouverFormulaireReponse() {
    const ze = zoneEdition();
    if (ze) return blocEdition(ze);
    if (flottant && formulaireFlottant && formulaireFlottant.isConnected) return formulaireFlottant;
    return formulaireReponse();
  }
  function formulaireReponse() {
    const zone = zoneReponse();
    if (!zone) return null;
    let noeud = zone.parentElement;
    while (noeud && noeud !== document.body) {
      const boutonPoster = Array.from(noeud.querySelectorAll('button')).find(function (b) {

        return /^(Poster|Publier)$/.test(b.textContent.trim());
      });
      if (boutonPoster) return noeud;
      noeud = noeud.parentElement;
    }
    return null;
  }

  function numeroDuPost(post) {
    const m = post.id.match(/^post-(\d+)$/);
    return m ? m[1] : null;
  }

  function insererCitationDansZone(numero) {
    const zone = trouverZoneTexte();
    if (!zone) return;

    const citation = '>>' + numero + '\n';
    const debut = zone.selectionStart != null ? zone.selectionStart : zone.value.length;
    const fin = zone.selectionEnd != null ? zone.selectionEnd : zone.value.length;
    const avant = zone.value.slice(0, debut);
    const apres = zone.value.slice(fin);

    const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
    setter.call(zone, avant + citation + apres);
    zone.dispatchEvent(new Event('input', { bubbles: true }));

    const curseur = (avant + citation).length;
    zone.setSelectionRange(curseur, curseur);
    zone.focus();
  }

  let flottant = false;
  let formulaireFlottant = null;
  let entete = null;
  let placeholder = null;

  const OPACITE_PASTILLE_INACTIVE = '0.4';
  let boutonBascule = null;

  const PAGES_SANS_PASTILLE = /^\/(?:$|aide\/?$|regles\/?$|devlog(?:\/|$)|user\/|account(?:\/|$)|messages(?:\/|$)|moderation(?:\/|$))/;
  function pageAvecFormulaire() {
    if (PAGES_SANS_PASTILLE.test(location.pathname)) return false;
    return !!trouverFormulaireReponse();
  }

  function majEtatPastille() {
    if (!boutonBascule) return;
    boutonBascule.style.opacity = flottant ? '1' : String(Math.min(100, Math.max(5, +M.opacitePastille || 40)) / 100);
    const aff = flottant || (M.pastille && pageAvecFormulaire()) ? 'flex' : 'none';
    if (boutonBascule.style.display !== aff) boutonBascule.style.display = aff;
  }
  let redimensionneur = null;

  const CLE_TAILLE = 'nanachan-messages-plus-taille';

  const LARGEUR_DEFAUT = 420;
  const ESPACE_PAR_OUTIL = 10;
  const HAUTEUR_MIN_SECOURS = 160;

  function trouverBarreOutils(formulaire) {
    let noeud = trouverZoneTexte();
    for (let i = 0; i < 4 && noeud && noeud !== formulaire; i++) {
      let frere = noeud.nextElementSibling;
      while (frere) {
        if (frere.querySelectorAll('button, svg, img').length >= 3) return frere;
        frere = frere.nextElementSibling;
      }
      noeud = noeud.parentElement;
    }
    return null;
  }

  function largeurMinEffective() {
    const formulaire = trouverFormulaireReponse();
    const barre = formulaire && trouverBarreOutils(formulaire);
    let largeur = LARGEUR_DEFAUT;
    if (barre) {

      const autour = formulaire.getBoundingClientRect().width - barre.getBoundingClientRect().width;
      const ancienneLargeur = barre.style.width;
      const ancienRetour = barre.style.flexWrap;
      barre.style.width = 'max-content';
      barre.style.flexWrap = 'nowrap';

      const visibles = Array.from(barre.children).filter(function (c) { return c.offsetWidth > 0 && getComputedStyle(c).position !== 'absolute' && getComputedStyle(c).position !== 'fixed'; }).length;
      const besoin = barre.getBoundingClientRect().width + visibles * ESPACE_PAR_OUTIL;
      barre.style.width = ancienneLargeur;
      barre.style.flexWrap = ancienRetour;
      largeur = Math.ceil(besoin + Math.max(autour, 0));
    }
    return Math.min(largeur, window.innerWidth - 8);
  }

  function hauteurMinEffective() {
    const formulaire = trouverFormulaireReponse();
    if (!formulaire) return HAUTEUR_MIN_SECOURS;
    const ancienne = formulaire.style.height;
    formulaire.style.height = 'auto';
    const naturelle = formulaire.offsetHeight;
    formulaire.style.height = ancienne;
    return Math.min(naturelle || HAUTEUR_MIN_SECOURS, window.innerHeight - 8);
  }

  let observateurBarre = null;
  function surveillerBarreOutils(formulaire) {
    if (observateurBarre) observateurBarre.disconnect();
    const barre = trouverBarreOutils(formulaire);
    if (!barre) return;
    let attente = null;
    observateurBarre = new MutationObserver(function () {
      if (attente) return;
      attente = requestAnimationFrame(function () {
        attente = null;
        if (!flottant) return;
        appliquerLargeurMin(formulaire);
      });
    });
    observateurBarre.observe(barre, { childList: true, subtree: true });
  }

  let largeurMiniRetenue = 0;
  function largeurMinFenetre() {
    largeurMiniRetenue = Math.max(largeurMiniRetenue, largeurMinEffective());
    return Math.min(largeurMiniRetenue, window.innerWidth - 8);
  }
  function appliquerLargeurMin(formulaire) {
    const mini = largeurMinFenetre();
    if (formulaire.style.minWidth === mini + 'px') return;
    formulaire.style.minWidth = mini + 'px';
    if (formulaire.offsetWidth < mini) formulaire.style.width = mini + 'px';

    const rect = formulaire.getBoundingClientRect();
    if (rect.right > window.innerWidth - 4) positionner(formulaire, rect.left, rect.top);
  }

  const CLE_APERCU = 'nanachan-messages-plus-apercu';
  const CLE_HAUTEUR_APERCU = 'nanachan-messages-plus-hauteur-apercu';
  const ATTR_CACHE = 'data-mp-cache';
  const styleApercu = document.createElement('style');
  styleApercu.textContent = '[' + ATTR_CACHE + ']{display:none!important;}';
  document.head.appendChild(styleApercu);

  let apercuVisible = true;
  try { apercuVisible = localStorage.getItem(CLE_APERCU) !== '0'; } catch (e) {}
  let boutonApercu = null;
  let boiteApercuReglee = null;
  let observateurFormulaire = null;

  function trouverApercu(formulaire) {
    const tous = formulaire.querySelectorAll('*');
    let etiquette = null;
    for (let i = 0; i < tous.length; i++) {
      const el = tous[i];
      if (el.children.length === 0 && /^Aperçu du message/i.test(el.textContent.trim())) { etiquette = el; break; }
    }
    if (!etiquette) return null;
    let bloc = etiquette;
    while (bloc.parentElement && bloc.parentElement !== formulaire && !bloc.nextElementSibling) bloc = bloc.parentElement;
    const boite = bloc.nextElementSibling;
    const parent = bloc.parentElement;

    const aMasquer = (parent && parent !== formulaire && parent.children.length <= 2) ? [parent] : [bloc, boite].filter(Boolean);
    return { boite: boite, aMasquer: aMasquer, titre: etiquette };
  }

  function appliquerApercu() {
    const formulaire = trouverFormulaireReponse();
    if (!formulaire) return;
    formulaire.querySelectorAll('[' + ATTR_CACHE + ']').forEach(function (el) { el.removeAttribute(ATTR_CACHE); });
    const apercu = trouverApercu(formulaire);
    if (boutonApercu) {
      boutonApercu.style.display = (apercu && flottant) ? '' : 'none';
      boutonApercu.style.opacity = apercuVisible ? '1' : '0.55';
      boutonApercu.style.textDecoration = apercuVisible ? 'none' : 'line-through';
      boutonApercu.title = apercuVisible ? "Masquer l'aperçu du message" : "Afficher l'aperçu du message";
    }
    if (!apercu) return;
    if (flottant && !apercuVisible) {
      apercu.aMasquer.forEach(function (el) { el.setAttribute(ATTR_CACHE, ''); });
      return;
    }
    const boite = apercu.boite;
    if (boite && boite !== boiteApercuReglee) {
      retirerReglageBoite();
      reglerBoiteApercu(boite, apercu.titre);
      boiteApercuReglee = boite;
    }
  }

  const CLE_APERCU_TOUT = 'nanachan-messages-plus-apercu-tout';
  const ATTR_TITRE_APERCU = 'data-mp-titre-apercu';
  let apercuTout = false;
  try { apercuTout = localStorage.getItem(CLE_APERCU_TOUT) === '1'; } catch (e) {}
  styleApercu.textContent +=
    '[' + ATTR_TITRE_APERCU + ']{cursor:pointer;user-select:none;}' +
    '[' + ATTR_TITRE_APERCU + ']::after{content:attr(' + ATTR_TITRE_APERCU + ');margin-left:8px;font-size:.85em;opacity:.55;}' +
    '[' + ATTR_TITRE_APERCU + ']:hover::after{opacity:1;text-decoration:underline;}';
  const boitesApercu = new Set();
  function hauteurMemorisee() {
    try { return parseInt(localStorage.getItem(CLE_HAUTEUR_APERCU), 10) || 0; } catch (e) { return 0; }
  }
  function modeBoiteApercu(boite) {
    boite.style.setProperty('max-height', 'none', 'important');
    boite.style.boxSizing = 'border-box';
    if (apercuTout) {
      boite.style.resize = 'none';
      boite.style.overflow = 'visible';
      boite.style.setProperty('height', 'auto', 'important');
    } else {
      boite.style.resize = 'vertical';
      boite.style.overflow = 'auto';
      const h = hauteurMemorisee();
      boite.style.removeProperty('height');
      boite.style.height = h ? h + 'px' : '';
    }

    if (boite._mpTitre) boite._mpTitre.setAttribute(ATTR_TITRE_APERCU, apercuTout ? '⤡ réduire' : '⤢ tout afficher');
  }
  function basculerApercuTout() {
    apercuTout = !apercuTout;
    try { localStorage.setItem(CLE_APERCU_TOUT, apercuTout ? '1' : '0'); } catch (e) {}
    boitesApercu.forEach(function (b) {
      if (!b.isConnected) { boitesApercu.delete(b); return; }
      modeBoiteApercu(b);
    });
    libererHauteur();
  }
  function reglerBoiteApercu(boite, titre) {
    if (!boite._mpReglee) {
      boite._mpReglee = true;

      if (!boite.style.minHeight) boite.style.minHeight = Math.min(Math.max(boite.offsetHeight, 28), 60) + 'px';

      boite.addEventListener('mousedown', libererHauteur);
      boite.addEventListener('dblclick', function (e) {
        const r = boite.getBoundingClientRect();
        if (e.clientX > r.right - 24 && e.clientY > r.bottom - 24) { e.preventDefault(); basculerApercuTout(); }
      });
    }
    if (titre && !titre._mpClic) {
      titre._mpClic = true;
      titre.title = 'Clic : tout afficher / réduire l\'aperçu (double-clic sur son coin aussi)';
      titre.addEventListener('click', basculerApercuTout);
    }
    if (titre) boite._mpTitre = titre;
    boitesApercu.add(boite);
    modeBoiteApercu(boite);
  }

  document.addEventListener('mouseup', function () {
    if (apercuTout) return;
    const memo = hauteurMemorisee();
    boitesApercu.forEach(function (b) {
      if (!b.isConnected || !b.style.height) return;
      const h = b.offsetHeight;
      if (h !== memo && parseInt(b.style.height, 10) !== memo) {
        try { localStorage.setItem(CLE_HAUTEUR_APERCU, String(h)); } catch (e) {}
      }
    });
  });

  let attenteGlobale = null;
  new MutationObserver(function (__ecoMs) {
    if (!ecoChangementUtile(__ecoMs)) return;
    if (attenteGlobale) return;
    attenteGlobale = requestAnimationFrame(function () {
      attenteGlobale = null;

      if (flottant && (!formulaireFlottant || !formulaireFlottant.isConnected)) replierFormulaire();

      else if (flottant && formulaireFlottant.closest('.post-container[id^="post-"]') && !formulaireFlottant.querySelector('textarea')) replierFormulaire();
      if (!boiteApercuReglee || !boiteApercuReglee.isConnected) appliquerApercu();
      majEtatPastille();
    });
  }).observe(document.body, { childList: true, subtree: true });
  window.addEventListener('popstate', function () { setTimeout(majEtatPastille, 0); });

  function libererHauteur() {
    const formulaire = trouverFormulaireReponse();
    if (formulaire && flottant && modeAuto()) formulaire.style.height = 'auto';
  }

  function modeAuto() { return M.taille !== 'libre'; }
  function ecrireModeTaille(mode) {
    M.taille = mode;
    try {
      const lu = JSON.parse(localStorage.getItem(CLE_REGLAGES) || '{}') || {};
      lu.taille = mode;
      localStorage.setItem(CLE_REGLAGES, JSON.stringify(lu));
    } catch (e) {  }
  }
  let boutonTaille = null;
  function majBoutonTaille() {
    if (!boutonTaille) return;
    const auto = modeAuto();
    boutonTaille.textContent = auto ? '↕ Auto' : '⤡ Libre';
    boutonTaille.style.borderStyle = auto ? 'solid' : 'dashed';
    boutonTaille.title = auto
      ? 'Taille auto : la fenêtre prend la taille de son contenu. Clic, ou tirer la poignée : taille libre'
      : 'Taille libre (tirée à la poignée). Clic : taille auto (tout le formulaire visible)';
  }

  function ajusterAuto() {
    const f = formulaireFlottant;
    if (!flottant || !f || !f.isConnected || !modeAuto()) return;
    const plafond = (window.innerHeight - 8) + 'px';
    if (f.style.maxHeight !== plafond) f.style.maxHeight = plafond;
    const r = f.getBoundingClientRect();
    if (r.bottom > window.innerHeight - 4 || r.top < 4) positionner(f, r.left, r.top);
  }
  function appliquerModeTaille(depuisReglages) {
    majBoutonTaille();
    const f = formulaireFlottant;
    if (!flottant || !f || !f.isConnected) return;
    poserMargesMode(f);
    if (modeAuto()) {
      reinitialiserTailleSauvegardee();
      f.style.width = largeurAuto() + 'px';
      f.style.height = 'auto';
      f.style.minHeight = '';
      ajusterAuto();
    } else {
      f.style.minHeight = '';
      f.style.maxHeight = (window.innerHeight - 8) + 'px';
      const t = lireTailleSauvegardee();
      if (t) {
        f.style.width = largeurVoulue() + 'px';
        f.style.height = Math.min(Math.max(t.hauteur, hauteurMiniLibre(f)), window.innerHeight - 8) + 'px';
      } else {

        f.style.height = f.offsetHeight + 'px';
        sauvegarderTaille(f.offsetWidth, f.offsetHeight);
      }
      const r = f.getBoundingClientRect();
      positionner(f, r.left, r.top);
    }
    placerPoignee();
  }
  window.addEventListener('resize', function () { ajusterAuto(); });

  function largeurAuto() {
    return Math.min(Math.max(largeurMinFenetre(), 320), window.innerWidth - 8);
  }
  function largeurVoulue() {
    if (!modeAuto()) {
      const t = lireTailleSauvegardee();
      if (t) return Math.min(Math.max(t.largeur, largeurMinFenetre()), window.innerWidth - 8);
    }
    return largeurAuto();
  }

  function poserMargesMode(f) {
    if (f._mpPaddingBasCalc === undefined) f._mpPaddingBasCalc = getComputedStyle(f).paddingBottom || '0px';
    const auto = modeAuto();
    f.style.paddingBottom = 'calc(' + f._mpPaddingBasCalc + ' + ' + 18 + 'px)';
    f.toggleAttribute('data-mp-auto', auto);
  }

  function retirerReglageBoite() {
    if (!boiteApercuReglee) return;
    boiteApercuReglee.style.resize = '';
    boiteApercuReglee.style.overflow = '';
    boiteApercuReglee.style.height = '';
    boiteApercuReglee.style.removeProperty('max-height');
    boitesApercu.delete(boiteApercuReglee);
    boiteApercuReglee = null;
  }

  function surveillerFormulaire(formulaire) {
    if (observateurFormulaire) observateurFormulaire.disconnect();
    let attente = null;
    observateurFormulaire = new MutationObserver(function () {
      if (attente) return;
      attente = requestAnimationFrame(function () {
        attente = null;
        if (flottant) { appliquerApercu(); finitionFenetre(formulaire); }
      });
    });
    observateurFormulaire.observe(formulaire, { childList: true, subtree: true });
  }

  function basculerApercu() {
    apercuVisible = !apercuVisible;
    try { localStorage.setItem(CLE_APERCU, apercuVisible ? '1' : '0'); } catch (e) {}
    libererHauteur();
    appliquerApercu();
  }

  function hauteurMiniLibre(f) {
    if (!f) return 120;
    const barre = trouverBarreOutils(f);
    const zone = f.querySelector('textarea');
    const repere = barre || zone;
    if (!repere) return 120;
    const rf = f.getBoundingClientRect();
    let bas = repere.getBoundingClientRect().bottom - rf.top + f.scrollTop + 8;
    const rangee = f.querySelector(':scope > [data-mp-boutons]');
    if (rangee) bas += rangee.offsetHeight;
    else bas += 18;
    const bord = parseFloat(getComputedStyle(f).borderBottomWidth) || 0;
    return Math.min(Math.max(120, Math.ceil(bas + bord)), window.innerHeight - 8);
  }
  function lireTailleSauvegardee() {
    try {
      const brut = localStorage.getItem(CLE_TAILLE);
      if (!brut) return null;
      const donnees = JSON.parse(brut);
      if (typeof donnees.largeur === 'number' && typeof donnees.hauteur === 'number') {
        return donnees;
      }
    } catch (e) {

    }
    return null;
  }

  function sauvegarderTaille(largeur, hauteur) {
    try {
      localStorage.setItem(CLE_TAILLE, JSON.stringify({ largeur: largeur, hauteur: hauteur }));
    } catch (e) {

    }
  }

  function reinitialiserTailleSauvegardee() {
    try {
      localStorage.removeItem(CLE_TAILLE);
    } catch (e) {

    }
  }

  function assurerPlaceholder(formulaire) {
    if (placeholder && placeholder.isConnected) return placeholder;

    placeholder = document.createElement('div');
    placeholder.style.padding = '16px';
    placeholder.style.border = '1px dashed var(--border-color, #373B41)';
    placeholder.style.borderRadius = '6px';
    placeholder.style.display = 'flex';
    placeholder.style.alignItems = 'center';
    placeholder.style.justifyContent = 'center';
    placeholder.style.color = 'var(--text-color, #C5C8C6)';
    placeholder.style.opacity = '0.85';
    placeholder.style.fontSize = '13px';

    const boutonRamener = document.createElement('button');
    boutonRamener.type = 'button';
    boutonRamener.textContent = 'Ramener ici';
    boutonRamener.style.background = 'var(--button-color, #373B41)';
    boutonRamener.style.color = 'var(--button-text-color, #C5C8C6)';
    boutonRamener.style.border = 'none';
    boutonRamener.style.borderRadius = '4px';
    boutonRamener.style.padding = '6px 12px';
    boutonRamener.style.cursor = 'pointer';
    boutonRamener.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      replierFormulaire();
      formulaire.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
    placeholder.appendChild(boutonRamener);

    formulaire.parentElement.insertBefore(placeholder, formulaire);
    return placeholder;
  }

  const styleDeplacement = document.createElement('style');
  styleDeplacement.textContent = 'html[data-mp-deplacement] iframe,html[data-mp-deplacement] embed,html[data-mp-deplacement] object{pointer-events:none!important;}';
  document.head.appendChild(styleDeplacement);
  function deplacementEnCours(oui) {
    if (document.documentElement.hasAttribute('data-mp-deplacement') !== oui) document.documentElement.toggleAttribute('data-mp-deplacement', oui);
  }

  function positionner(formulaire, gauche, haut) {
    const marge = 4;
    const largeur = formulaire.offsetWidth;
    const hauteur = formulaire.offsetHeight;
    gauche = Math.min(Math.max(gauche, marge), window.innerWidth - largeur - marge);
    haut = Math.min(Math.max(haut, marge), window.innerHeight - hauteur - marge);
    formulaire.style.left = gauche + 'px';
    formulaire.style.top = haut + 'px';
    placerPoignee();
  }

  function glisserAvecPointeur(el, debut, bouger, fin) {
    el.style.touchAction = 'none';
    el.addEventListener('pointerdown', function (e) {
      if (e.pointerType === 'mouse' && e.button !== 0) return;
      if (debut(e) === false) return;
      e.preventDefault();
      e.stopPropagation();
      const id = e.pointerId;
      try { el.setPointerCapture(id); } catch (err) {  }
      deplacementEnCours(true);
      function mv(ev) { if (ev.pointerId === id) bouger(ev); }
      function up(ev) {
        if (ev.pointerId !== id) return;
        el.removeEventListener('pointermove', mv);
        el.removeEventListener('pointerup', up);
        el.removeEventListener('pointercancel', up);
        try { el.releasePointerCapture(id); } catch (err) {  }
        deplacementEnCours(false);
        fin(ev);
      }
      el.addEventListener('pointermove', mv);
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
    });
  }

  function assurerEntete(formulaire) {
    if (entete && entete.isConnected) return entete;

    entete = document.createElement('div');
    entete.setAttribute('data-mp-entete', '');

    entete.style.position = 'sticky';
    entete.style.top = '0';
    entete.style.zIndex = '5';
    entete.style.display = 'flex';
    entete.style.alignItems = 'center';
    entete.style.justifyContent = 'space-between';
    entete.style.padding = '4px 8px';
    entete.style.marginBottom = '6px';
    entete.style.background = 'var(--button-color, #373B41)';
    entete.style.color = 'var(--button-text-color, #C5C8C6)';
    entete.style.borderRadius = '5px 5px 0 0';
    entete.style.cursor = 'move';
    entete.style.fontSize = '12px';
    entete.style.userSelect = 'none';

    const titre = document.createElement('span');
    titre.textContent = 'Messages+';
    entete.appendChild(titre);

    const groupe = document.createElement('span');
    groupe.style.display = 'flex';
    groupe.style.alignItems = 'center';
    groupe.style.gap = '6px';
    entete.appendChild(groupe);

    boutonTaille = document.createElement('span');
    boutonTaille.setAttribute('data-mp-bouton', '');
    boutonTaille.setAttribute('data-mp-taille', '');
    boutonTaille.style.cursor = 'pointer';
    boutonTaille.style.padding = '0 6px';
    boutonTaille.style.border = '1px solid currentColor';
    boutonTaille.style.borderRadius = '3px';
    boutonTaille.style.fontSize = '11px';
    boutonTaille.style.whiteSpace = 'nowrap';
    boutonTaille.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      ecrireModeTaille(modeAuto() ? 'libre' : 'auto');
      appliquerModeTaille();
    });
    groupe.appendChild(boutonTaille);
    majBoutonTaille();

    boutonApercu = document.createElement('span');
    boutonApercu.textContent = 'Aperçu';
    boutonApercu.setAttribute('data-mp-bouton', '');
    boutonApercu.setAttribute('data-mp-bouton-apercu', '');
    boutonApercu.style.cursor = 'pointer';
    boutonApercu.style.padding = '0 6px';
    boutonApercu.style.border = '1px solid currentColor';
    boutonApercu.style.borderRadius = '3px';
    boutonApercu.style.fontSize = '11px';
    boutonApercu.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      basculerApercu();
    });
    groupe.appendChild(boutonApercu);

    const boutonFermer = document.createElement('span');
    boutonFermer.textContent = '✕';
    boutonFermer.style.cursor = 'pointer';
    boutonFermer.style.padding = '0 4px';
    boutonFermer.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      replierFormulaire();
    });
    groupe.appendChild(boutonFermer);

    formulaire.insertBefore(entete, formulaire.firstChild);

    let decalageX = 0;
    let decalageY = 0;
    glisserAvecPointeur(entete, function (e) {
      if (e.target === boutonFermer || (e.target.closest && e.target.closest('[data-mp-bouton]'))) return false;
      const rect = formulaire.getBoundingClientRect();
      decalageX = e.clientX - rect.left;
      decalageY = e.clientY - rect.top;
    }, function (e) {
      positionner(formulaire, e.clientX - decalageX, e.clientY - decalageY);
    }, function () {  });

    return entete;
  }

  function assurerRedimensionneur(formulaire) {
    if (redimensionneur && redimensionneur.isConnected) return redimensionneur;

    const doigt = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
    const cote = doigt ? 22 : 14;
    redimensionneur = document.createElement('div');
    redimensionneur.setAttribute('data-eco-ui', '');
    redimensionneur.setAttribute('data-mp-poignee', '');
    redimensionneur.title = 'Glisser pour redimensionner';
    redimensionneur.style.cssText = 'position:fixed;z-index:9999;width:' + cote + 'px;height:' + cote + 'px;cursor:nwse-resize;display:none;';

    if (!formulaire._mpSurvolEcoute) {
      formulaire._mpSurvolEcoute = true;
      formulaire.addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse' && redimensionneur && flottant) redimensionneur.setAttribute('data-mp-survol', ''); });
      formulaire.addEventListener('pointerleave', function () { if (redimensionneur) redimensionneur.removeAttribute('data-mp-survol'); });
    }
    redimensionneur._mpCote = cote;

    let departX = 0;
    let departY = 0;
    let largeurDepart = 0;
    let hauteurDepart = 0;
    let largeurMini = 0;
    let hauteurMiniFenetre = 120;

    function hauteurMiniUtile() { return hauteurMiniLibre(formulaire); }
    function hauteurMiniUtileAncienne() {
      const barre = trouverBarreOutils(formulaire);
      if (!barre) return 120;
      const rf = formulaire.getBoundingClientRect();
      const basBarre = barre.getBoundingClientRect().bottom;

      let suivant = Infinity;
      formulaire.querySelectorAll('*').forEach(function (el) {
        if (el.contains(barre) || barre.contains(el) || (entete && entete.contains(el))) return;
        const r = el.getBoundingClientRect();
        if (r.height > 0 && r.width > 0 && r.top >= basBarre - 0.5) suivant = Math.min(suivant, r.top);
      });
      const fin = Math.max(basBarre + 2, Math.min(basBarre + 8, suivant - 1));
      const bas = fin - rf.top + formulaire.scrollTop;

      const bord = parseFloat(getComputedStyle(formulaire).borderBottomWidth) || 0;
      return Math.max(120, Math.floor(bas + bord));
    }

    glisserAvecPointeur(redimensionneur, function (e) {
      redimensionneur.setAttribute('data-mp-tire', '');

      if (modeAuto()) {
        ecrireModeTaille('libre');
        formulaire.style.minHeight = '';
        poserMargesMode(formulaire);
        majBoutonTaille();
      }
      departX = e.clientX;
      departY = e.clientY;
      largeurDepart = formulaire.offsetWidth;
      hauteurDepart = formulaire.offsetHeight;
      largeurMini = largeurMinFenetre();
      hauteurMiniFenetre = hauteurMiniUtile();
      formulaire.style.maxHeight = (window.innerHeight - 8) + 'px';
    }, function (e) {
      const rect = formulaire.getBoundingClientRect();
      const largeurMax = window.innerWidth - rect.left - 4;
      const hauteurMax = window.innerHeight - rect.top - 4;
      const nouvelleLargeur = Math.max(Math.min(largeurDepart + (e.clientX - departX), largeurMax), Math.min(largeurMini, largeurMax));
      const nouvelleHauteur = Math.max(Math.min(hauteurDepart + (e.clientY - departY), hauteurMax), Math.min(hauteurMiniFenetre, hauteurMax));
      formulaire.style.width = nouvelleLargeur + 'px';
      formulaire.style.height = nouvelleHauteur + 'px';
      placerPoignee();
    }, function () {
      redimensionneur.removeAttribute('data-mp-tire');
      if (!modeAuto()) sauvegarderTaille(formulaire.offsetWidth, formulaire.offsetHeight);
    });

    document.body.appendChild(redimensionneur);
    return redimensionneur;
  }

  function placerPoignee() {
    if (!redimensionneur || !redimensionneur.isConnected) return;
    const f = formulaireFlottant;
    if (!flottant || !f || !f.isConnected) { redimensionneur.style.display = 'none'; return; }
    const r = f.getBoundingClientRect();
    const c = redimensionneur._mpCote || 18;

    redimensionneur.style.left = Math.round(r.right - c - 4) + 'px';
    redimensionneur.style.top = Math.round(r.bottom - c - 4) + 'px';
    redimensionneur.style.display = '';
  }
  let observateurTaille = null;
  window.addEventListener('resize', placerPoignee);

  function deplierFormulaire(spanCible) {
    const formulaire = trouverFormulaireReponse();
    if (!formulaire) return null;

    if (flottant && formulaireFlottant !== formulaire) replierFormulaire();

    if (!flottant) {
      formulaireFlottant = formulaire;
      largeurMiniRetenue = 0;

      formulaire._mpPaddingBas = formulaire.style.paddingBottom;
      formulaire._mpPaddingBasCalc = undefined;
      poserMargesMode(formulaire);
      formulaire.style.position = 'fixed';
      formulaire.style.zIndex = '9998';
      formulaire.style.width = 'min(' + LARGEUR_DEFAUT + 'px, calc(100vw - 8px))';
      formulaire.style.height = 'auto';
      formulaire.style.maxHeight = (window.innerHeight - 8) + 'px';
      formulaire.style.overflowY = 'auto';
      formulaire.style.overflowX = 'hidden';
      formulaire.style.boxSizing = 'border-box';
      formulaire.classList.add(CLASSE_SANS_BARRES);
      finitionFenetre(formulaire, true);
      formulaire.style.border = '1px solid var(--border-color, #373B41)';
      formulaire.style.borderRadius = '6px';
      formulaire.style.boxShadow = '0 6px 24px rgba(0,0,0,.5)';
      formulaire.style.background = 'var(--nana-background-color, #1a1c1e)';

      assurerEntete(formulaire);

      {
        const post = formulaire.closest('.post-container[id^="post-"]');
        const t = entete.firstChild;
        const txt = post ? '✎ Édition de ton post n° ' + (numeroDuPost(post) || '?') : 'Messages+';
        if (t && t.textContent !== txt) t.textContent = txt;
        entete.toggleAttribute('data-mp-edition', !!post);
        entete.title = post ? 'Tu modifies ce post (Confirmer / Annuler en bas de la fenêtre). N° d\'un post cliqué : >>n ajouté ici.' : '';
      }

      entete.style.top = '-' + (parseFloat(getComputedStyle(formulaire).paddingTop) || 0) + 'px';
      assurerPlaceholder(formulaire);
      assurerRedimensionneur(formulaire);
      flottant = true;
      appliquerApercu();
      appliquerLargeurMin(formulaire);
      surveillerBarreOutils(formulaire);
      surveillerFormulaire(formulaire);

      const tailleSauvegardee = modeAuto() ? null : lireTailleSauvegardee();
      formulaire.style.width = largeurVoulue() + 'px';
      if (tailleSauvegardee) {
        formulaire.style.height = Math.min(Math.max(tailleSauvegardee.hauteur, hauteurMiniLibre(formulaire)), window.innerHeight - 8) + 'px';
      }
      if (observateurTaille) observateurTaille.disconnect();
      if (window.ResizeObserver) {
        observateurTaille = new ResizeObserver(function () { placerPoignee(); ajusterAuto(); });
        observateurTaille.observe(formulaire);
      }

      const rect = spanCible ? spanCible.getBoundingClientRect() : null;
      const gauche = rect ? rect.left : window.innerWidth - formulaire.offsetWidth - 20;
      const haut = rect ? rect.bottom + 8 : 80;
      positionner(formulaire, gauche, haut);

      flottant = true;
      majBoutonTaille();
      ajusterAuto();
      placerPoignee();
      majEtatPastille();
    }

    return formulaire;
  }

  function replierFormulaire() {
    if (observateurBarre) { observateurBarre.disconnect(); observateurBarre = null; }
    if (observateurFormulaire) { observateurFormulaire.disconnect(); observateurFormulaire = null; }
    if (observateurTaille) { observateurTaille.disconnect(); observateurTaille = null; }
    document.querySelectorAll('[' + ATTR_CACHE + ']').forEach(function (el) { el.removeAttribute(ATTR_CACHE); });
    const formulaire = formulaireFlottant || trouverFormulaireReponse();
    formulaireFlottant = null;
    largeurMiniRetenue = 0;
    if (formulaire) {
      if (formulaire._mpPaddingBas !== undefined) { formulaire.style.paddingBottom = formulaire._mpPaddingBas; formulaire._mpPaddingBas = undefined; }
      formulaire._mpPaddingBasCalc = undefined;
      formulaire.removeAttribute('data-mp-auto');
      formulaire.removeAttribute('data-mp-fenetre');
      formulaire.querySelectorAll('[data-mp-boutons]').forEach(function (c) { c.removeAttribute('data-mp-boutons'); });
      formulaire.style.minHeight = '';
      formulaire.style.position = '';
      formulaire.style.zIndex = '';
      formulaire.style.width = '';
      formulaire.style.minWidth = '';
      formulaire.style.height = '';
      formulaire.style.maxHeight = '';
      formulaire.style.overflowY = '';
      formulaire.style.overflowX = '';
      formulaire.style.left = '';
      formulaire.style.top = '';
      formulaire.style.boxShadow = '';
      formulaire.style.border = '';
      formulaire.style.borderRadius = '';
      formulaire.style.background = '';
      formulaire.style.boxSizing = '';
      formulaire.classList.remove(CLASSE_SANS_BARRES);
    }

    if (modeAuto()) reinitialiserTailleSauvegardee();
    if (entete && entete.isConnected) entete.remove();
    boutonTaille = null;
    if (placeholder && placeholder.isConnected) placeholder.remove();
    if (redimensionneur && redimensionneur.isConnected) redimensionneur.remove();
    flottant = false;
    majEtatPastille();
  }

  document.addEventListener(
    'click',
    function (e) {
      if (!M.clicNumero) return;
      const numeroEl = e.target.closest && e.target.closest('p.numero');
      if (!numeroEl) return;

      const post = numeroEl.closest('.post-container[id^="post-"]');
      if (!post) return;

      const numero = numeroDuPost(post);
      if (!numero) return;

      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      const formulaire = deplierFormulaire(numeroEl);
      if (!formulaire) return;

      insererCitationDansZone(numero);
    },
    true
  );

  function creerBoutonBascule() {
    const bouton = document.createElement('button');
    bouton.type = 'button';
    bouton.textContent = '✎';
    bouton.title = 'Messages+ : réponse flottante';
    bouton.setAttribute('data-messages-plus-bascule', '');
    bouton.style.position = 'fixed';
    bouton.style.right = '16px';
    bouton.style.bottom = '16px';
    bouton.style.width = '44px';
    bouton.style.height = '44px';
    bouton.style.borderRadius = '50%';
    bouton.style.border = 'none';
    bouton.style.display = 'flex';
    bouton.style.alignItems = 'center';
    bouton.style.justifyContent = 'center';
    bouton.style.background = 'var(--button-color, #373B41)';
    bouton.style.color = 'var(--button-text-color, #C5C8C6)';
    bouton.style.fontSize = '18px';
    bouton.style.cursor = 'pointer';
    bouton.style.boxShadow = '0 2px 10px rgba(0,0,0,.45)';
    bouton.style.zIndex = '9997';
    bouton.style.transition = 'background .25s ease, opacity .25s ease';
    bouton.style.touchAction = 'manipulation';

    let minuteurAppui = null;
    function relacherAppui() {
      clearTimeout(minuteurAppui);
      minuteurAppui = setTimeout(function () { bouton.classList.remove(CLASSE_APPUI); }, 250);
    }
    bouton.addEventListener('pointerdown', function (e) {
      if (e.button !== 0) return;
      clearTimeout(minuteurAppui);
      bouton.classList.add(CLASSE_APPUI);
    });
    bouton.addEventListener('pointerup', relacherAppui);
    bouton.addEventListener('pointercancel', relacherAppui);
    bouton.addEventListener('pointerleave', relacherAppui);

    bouton.addEventListener('mouseenter', function () {
      bouton.style.background = 'var(--button-hover-color, #45494f)';
    });
    bouton.addEventListener('mouseleave', function () {
      bouton.style.background = 'var(--button-color, #373B41)';
    });

    bouton.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (flottant) {
        replierFormulaire();
      } else {
        deplierFormulaire(null);
      }
    });

    document.body.appendChild(bouton);
    boutonBascule = bouton;
    majEtatPastille();
  }

  creerBoutonBascule();
  appliquerApercu();

  const ATTR_APERCU_EDITION = 'data-mp-apercu-edition';
  const setterZone = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
  let rendusEnCours = 0;

  function ecrireZone(zone, valeur) {
    setterZone.call(zone, valeur);
    zone.dispatchEvent(new Event('input', { bubbles: true }));
  }
  function attendreMicrotaches() {
    return Promise.resolve().then(function () { return Promise.resolve(); }).then(function () { return Promise.resolve(); });
  }
  function aConfirmer(el) {
    return Array.from(el.querySelectorAll('button')).some(function (b) { return /^Confirmer$/i.test(b.textContent.trim()); });
  }

  function blocEdition(zone) {
    let n = zone.parentElement;
    while (n && !n.classList.contains('post-container')) {
      if (aConfirmer(n)) return n;
      n = n.parentElement;
    }
    return null;
  }

  function rangeeBoutons(bloc) {
    return Array.from(bloc.children).find(function (c) {
      return aConfirmer(c) || (c.tagName === 'BUTTON' && /^(Annuler|Confirmer)$/i.test(c.textContent.trim()));
    }) || null;
  }

  const DELAIS_CONTROLE = [600, 1500, 3000];
  function planifierControle(zoneEdition, cadre, niveau) {
    clearTimeout(cadre._minControle);
    if (niveau >= DELAIS_CONTROLE.length) return;
    cadre._minControle = setTimeout(function () {
      if (!cadre.isConnected || !zoneEdition.isConnected) return;
      if (zoneEdition.value !== cadre._dernierTexte) return;
      rendreApercuEdition(zoneEdition, cadre, true, niveau + 1);
    }, DELAIS_CONTROLE[niveau]);
  }
  function rendreApercuEdition(zoneEdition, cadre, force, controle) {
    cadre._chaine = (cadre._chaine || Promise.resolve()).then(function () {
      return rendreApercuEditionMaintenant(zoneEdition, cadre, force);
    }).then(function (res) {
      if (!res || !res.copie) return;
      if (!controle) planifierControle(zoneEdition, cadre, 0);
      else if (res.change) planifierControle(zoneEdition, cadre, controle);
    }).catch(function (e) { console.warn('[Messages+] aperçu de l\'édition :', e); });
    return cadre._chaine;
  }

  function clicSansPropager(el) {
    const parent = el.parentNode;
    if (!parent) return;
    const suivant = el.nextSibling;
    parent.removeChild(el);
    try { el.click(); } finally { parent.insertBefore(el, suivant); }
  }
  function attendreRenduSite(formulaire, htmlAvant) {
    return attendreMicrotaches().then(function () {
      const ap = trouverApercu(formulaire);
      if (ap && ap.boite && ap.boite.innerHTML !== htmlAvant) return;
      return new Promise(function (ok) {
        const fin = setTimeout(function () { obs.disconnect(); ok(); }, 300);
        const obs = new MutationObserver(function () { clearTimeout(fin); obs.disconnect(); ok(); });
        obs.observe(formulaire, { childList: true, subtree: true, characterData: true, attributes: true });
      }).then(attendreMicrotaches);
    });
  }

  async function ouvrirSpoilersSite(formulaire, cadre) {
    const bascules = [];
    const voulus = cadre._spoilsOuverts;
    if (!voulus || !voulus.size) return bascules;

    for (let passe = 0; passe < 4; passe++) {
      const ap = trouverApercu(formulaire);
      if (!ap || !ap.boite) break;
      const envs = Array.from(ap.boite.querySelectorAll('.spoiler-wrapper'));
      let change = false;
      envs.forEach(function (env, i) {
        if (!voulus.has(i) || bascules.indexOf(i) !== -1) return;
        const b = env.querySelector(':scope > .spoiler');
        if (!b || b.classList.contains('is-active')) return;
        clicSansPropager(b);
        bascules.push(i);
        change = true;
      });
      if (!change) break;
      await attendreRenduSite(formulaire, ap.boite.innerHTML);
    }
    return bascules;
  }
  function refermerSpoilersSite(formulaire, bascules) {
    if (!bascules.length) return;
    const ap = trouverApercu(formulaire);
    if (!ap || !ap.boite) return;
    const envs = Array.from(ap.boite.querySelectorAll('.spoiler-wrapper'));

    bascules.slice().sort(function (a, b) { return b - a; }).forEach(function (i) {
      const b = envs[i] && envs[i].querySelector(':scope > .spoiler');
      if (b && b.classList.contains('is-active')) clicSansPropager(b);
    });
  }

  async function rendreApercuEditionMaintenant(zoneEdition, cadre, force) {
    const zoneRep = zoneReponse();
    const formulaire = formulaireReponse();
    if (!zoneRep || !formulaire) {
      cadre._boite.textContent = '(aperçu indisponible : pas de « Répondre au topic » sur cette page)';
      return;
    }
    const texte = zoneEdition.value;
    if (!force && cadre._dernierTexte === texte) return;
    cadre._dernierTexte = texte;
    cadre.style.display = texte.trim() ? '' : 'none';
    if (!texte.trim()) return;
    const avant = zoneRep.value;
    const selDebut = zoneRep.selectionStart;
    const selFin = zoneRep.selectionEnd;
    rendusEnCours++;
    let html = null;
    try {
      const apAvant = trouverApercu(formulaire);
      const htmlAvant = apAvant && apAvant.boite ? apAvant.boite.innerHTML : null;
      ecrireZone(zoneRep, texte);
      await attendreMicrotaches();
      let ap = trouverApercu(formulaire);

      if (texte !== avant && (!ap || !ap.boite || ap.boite.innerHTML === htmlAvant)) {
        await new Promise(function (ok) {
          const fin = setTimeout(function () { obs.disconnect(); ok(); }, 300);
          const obs = new MutationObserver(function () { clearTimeout(fin); obs.disconnect(); ok(); });
          obs.observe(formulaire, { childList: true, subtree: true, characterData: true });
        });
        await attendreMicrotaches();
        ap = trouverApercu(formulaire);
      }

      let bascules = [];
      try {
        bascules = await ouvrirSpoilersSite(formulaire, cadre);
        if (bascules.length) ap = trouverApercu(formulaire);
      } catch (e) {  }
      if (ap && ap.boite) {
        html = ap.boite.innerHTML;

        Array.from(ap.boite.attributes).forEach(function (a) {
          if (a.name === 'style' || a.name === 'id' || a.name === ATTR_CACHE) return;
          if (cadre._boite.getAttribute(a.name) !== a.value) cadre._boite.setAttribute(a.name, a.value);
        });
        if (ap.titre) Array.from(ap.titre.attributes).forEach(function (a) {
          if (a.name !== 'style' && a.name !== 'id' && a.name !== ATTR_CACHE) cadre._titre.setAttribute(a.name, a.value);
        });
      }
      try { refermerSpoilersSite(formulaire, bascules); } catch (e) {  }
    } finally {
      ecrireZone(zoneRep, avant);
      try { zoneRep.setSelectionRange(selDebut, selFin); } catch (e) {  }
      rendusEnCours--;
    }
    if (html === null) { cadre._boite.textContent = '(aperçu indisponible)'; cadre._htmlBrut = null; return null; }

    const change = html !== cadre._htmlBrut;
    if (change || !cadre._boite.firstChild) {
      cadre._htmlBrut = html;
      cadre._boite.innerHTML = html;
      remettreSpoilers(cadre);
    }
    return { copie: true, change: change };
  }

  function spoilersDe(cadre) { return Array.from((cadre._boite || cadre).querySelectorAll('.spoiler-wrapper')); }
  function poserSpoiler(enveloppe, ouvert) {
    const bouton = enveloppe.querySelector(':scope > .spoiler');
    const boite = enveloppe.querySelector(':scope > .spoiler-box');
    if (!bouton || !boite) return;
    bouton.classList.toggle('is-active', ouvert);
    boite.style.display = ouvert ? '' : 'none';
  }
  function remettreSpoilers(cadre) {
    if (!cadre._spoilsOuverts || !cadre._spoilsOuverts.size) return;
    spoilersDe(cadre).forEach(function (env, i) { if (cadre._spoilsOuverts.has(i)) poserSpoiler(env, true); });
  }
  document.addEventListener('click', function (e) {
    const bouton = e.target.closest && e.target.closest('[' + ATTR_APERCU_EDITION + '] .spoiler-wrapper > .spoiler');
    if (!bouton) return;
    const cadre = bouton.closest('[' + ATTR_APERCU_EDITION + ']');
    const env = bouton.parentElement;
    const boite = env.querySelector(':scope > .spoiler-box');
    if (!cadre || !boite) return;
    e.preventDefault();
    e.stopPropagation();
    const ouvrir = boite.style.display === 'none' || !bouton.classList.contains('is-active');
    poserSpoiler(env, ouvrir);
    const i = spoilersDe(cadre).indexOf(env);
    if (!cadre._spoilsOuverts) cadre._spoilsOuverts = new Set();
    if (ouvrir) cadre._spoilsOuverts.add(i); else cadre._spoilsOuverts.delete(i);

    if (ouvrir && cadre._zone && cadre._zone.isConnected) rendreApercuEdition(cadre._zone, cadre, true);
  });
  function installerApercuEdition(zone) {
    if (!M.apercuEdition) return;
    if (zone._mpApercu && zone._mpApercu.isConnected) return;
    const bloc = blocEdition(zone);
    if (!bloc) return;
    const cadre = document.createElement('div');
    cadre.setAttribute(ATTR_APERCU_EDITION, '');
    cadre.style.cssText = 'margin:10px 0;';
    const titre = document.createElement('div');
    titre.textContent = 'Aperçu du message';
    titre.style.cssText = 'margin-bottom:6px;';
    const boite = document.createElement('div');
    boite.style.cssText = 'min-height:28px;overflow:auto;resize:vertical;';
    cadre.appendChild(titre);
    cadre.appendChild(boite);
    cadre._boite = boite;
    cadre._titre = titre;
    cadre._zone = zone;
    bloc.insertBefore(cadre, rangeeBoutons(bloc));
    zone._mpApercu = cadre;
    reglerBoiteApercu(boite, titre);
    let minuteur = null;
    zone.addEventListener('input', function () {
      clearTimeout(minuteur);
      clearTimeout(cadre._minControle);
      minuteur = setTimeout(function () { rendreApercuEdition(zone, cadre); }, 250);
    });
    rendreApercuEdition(zone, cadre);
  }

  function surveillerEditions() {
    document.querySelectorAll('.post-container[id^="post-"] textarea').forEach(installerApercuEdition);

    document.querySelectorAll('[' + ATTR_APERCU_EDITION + ']').forEach(function (c) {
      if (!c.parentElement || !c.parentElement.querySelector('textarea')) c.remove();
    });
  }
  let editionPlanifiee = false;
  new MutationObserver(function (__ecoMs) {
    if (ecoApercusTouches(__ecoMs)) return;
    if (editionPlanifiee || rendusEnCours) return;
    editionPlanifiee = true;
    requestAnimationFrame(function () { editionPlanifiee = false; surveillerEditions(); });
  }).observe(document.body, { childList: true, subtree: true });
  surveillerEditions();

