  function normaliser(t) { return String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }
  function echapper(t) { return String(t).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function el(tag, cls, texte) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (texte != null) e.textContent = texte;
    return e;
  }
  function bouton(cls, texte, titre, action) {
    const b = el('button', cls, texte);
    b.type = 'button';
    if (titre) b.title = titre;
    b.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); action(e); });
    return b;
  }
  function attendre(test, ms, pas) {
    return new Promise(function (ok) {
      const debut = Date.now();
      (function essai() {
        let v = false;
        try { v = test(); } catch (e) { v = false; }
        if (v) return ok(true);
        if (Date.now() - debut > (typeof ms === 'function' ? ms() : ms)) return ok(false);
        setTimeout(essai, pas || 100);
      })();
    });
  }
  function nf(n) { return Number(n).toLocaleString('fr-FR'); }
  function monPseudo() {
    const a = document.querySelector('header .bouton-compte');
    return a ? (a.textContent || '').trim().split(/\s+/)[0] : '';
  }

  function decouperMots(texte) {
    const res = [];
    const re = /(-?)"([^"]+)"|(-?)([^\s"]+)/g;
    let m;
    while ((m = re.exec(texte || ''))) {
      const exclu = !!(m[1] || m[3]);
      const mot = (m[2] || m[4] || '').trim();
      if (!mot || mot === '-') continue;
      res.push({ mot: normaliser(mot), brut: mot, exclu: exclu, exact: !!m[2] });
    }
    return res;
  }
  const cacheRegex = new Map();
  function regexExacte(mot) {
    let re = cacheRegex.get(mot);
    if (!re) {
      re = new RegExp('(^|[^a-z0-9])' + mot.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^a-z0-9])');
      cacheRegex.set(mot, re);
    }
    return re;
  }
  function correspond(texte, m) { return m.exact ? regexExacte(m.mot).test(texte) : texte.indexOf(m.mot) !== -1; }

  const RE_JETONS = /\[media:([^\]\s]+)\]|https?:\/\/[^\s<>"']+/gi;
  const RE_IMAGE = /\.(?:png|jpe?g|gif|webp|avif|bmp)(?:[?#]|$)/i;
  function rendreLocal(texte, mini) {
    let html = '';
    let dernier = 0;
    let m;
    RE_JETONS.lastIndex = 0;
    while ((m = RE_JETONS.exec(texte))) {
      html += echapper(texte.slice(dernier, m.index));
      if (m[1]) {
        html += '<img class="sticker" data-mpp-img alt="" src="' + echapper('/media/uploads/' + m[1]) + '">';
      } else {
        let url = m[0];
        const ponct = url.match(/[.,;:!?)\]]+$/);
        if (ponct) url = url.slice(0, -ponct[0].length);
        const e = echapper(url);
        if (RE_IMAGE.test(url)) html += '<a href="' + e + '" target="_blank" rel="noopener noreferrer"><img class="sticker" data-mpp-img alt="" src="' + e + '"></a>';
        else {
          let affiche = url;
          if (mini) { try { affiche = '[' + new URL(url).hostname.replace(/^www\./, '') + ']'; } catch (x) { affiche = '[lien]'; } }
          html += '<a href="' + e + '" target="_blank" rel="noopener noreferrer">' + echapper(affiche) + '</a>';
        }
        RE_JETONS.lastIndex = m.index + url.length;
        dernier = m.index + url.length;
        continue;
      }
      dernier = m.index + m[0].length;
    }
    html += echapper(texte.slice(dernier));
    return html.replace(/\r?\n/g, '<br>');
  }

  function lireDate(t) {
    const m = String(t || '').match(/(\d{1,2})\/(\d{1,2})\/(\d{4})\D+(\d{1,2})[:h](\d{2})/);
    return m ? new Date(+m[3], +m[2] - 1, +m[1], +m[4], +m[5]) : null;
  }
  function cleJour(d) { return d.getFullYear() + '-' + d.getMonth() + '-' + d.getDate(); }
  function libelleJour(d) {
    const auj = new Date();
    const hier = new Date(auj.getFullYear(), auj.getMonth(), auj.getDate() - 1);
    if (cleJour(d) === cleJour(auj)) return 'Aujourd\'hui';
    if (cleJour(d) === cleJour(hier)) return 'Hier';
    const t = d.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
    return t.charAt(0).toUpperCase() + t.slice(1);
  }
  function heureTexte(d) { return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); }

