          const a = corps.match(/animation(?:-name)?\s*:\s*([^;]+)/);
          if (a) a[1].split(/[\s,]+/).forEach(function (n) { animations.add(n); });
          const texte = emballer(garder.join(',') + '{' + corps + '}');
