    i.placeholder = 'Filtrer les discussions (pseudo, dernier message)…';
    i.value = texteFiltre;
    i.addEventListener('input', function () { texteFiltre = i.value; appliquerFiltreListe(); });
    i.addEventListener('keydown', function (e) { e.stopPropagation(); if (e.key === 'Escape') { i.value = ''; texteFiltre = ''; appliquerFiltreListe(); } });
    champ.appendChild(i);
