  (function suivreGlisserNatif() {
    let minuteur = null;
    function fin() {
      clearTimeout(minuteur);
      document.documentElement.removeAttribute('data-rp-glisse-natif');
    }
    ['dragstart', 'dragenter', 'dragover'].forEach(function (t) {
      window.addEventListener(t, function () {
        if (!document.documentElement.hasAttribute('data-rp-glisse-natif')) document.documentElement.setAttribute('data-rp-glisse-natif', '');
        clearTimeout(minuteur);
        minuteur = setTimeout(fin, 400);
      }, true);
    });
    ['drop', 'dragend'].forEach(function (t) { window.addEventListener(t, fin, true); });
  })();

  const style = document.createElement('style');
