    basculeNav.style.cssText = 'display:inline-flex;align-items:center;justify-content:center;width:24px;height:22px;padding:0;background:none;border:1px solid transparent;' +
      'border-radius:5px;color:inherit;cursor:pointer;opacity:.75;';
