    boutonVue.style.cssText = 'display:inline-flex;align-items:center;gap:4px;background:none;border:1px solid #5A5F66;border-radius:12px;color:inherit;' +
      'padding:1px 8px;font-size:12px;font-weight:400;cursor:pointer;opacity:.85;';
