  function installerIconesPosts() {
    document.querySelectorAll('.reaction-menu .add-reaction-btn').forEach(function (plus) {
      const menuSite = plus.closest('.reaction-menu');
      if (!menuSite) return;
      if (!(plus.closest('[data-citation-inline], [data-citation-hover-preview]') && !menuSite.hasAttribute('data-cp-replique'))) installerQuickReacs(menuSite, plus);
      if (menuSite.querySelector('[' + ATTR_ICONE_POST + ']')) return;

      if (plus.closest('[data-citation-inline], [data-citation-hover-preview]') && !menuSite.hasAttribute('data-cp-replique')) return;
      copierSurvol(plus, ATTR_ICONE_POST);
      const padding = getComputedStyle(plus).padding;

      const etoile = creerIcone('favoris');
      etoile.setAttribute(ATTR_ICONE_POST, '');
      etoile.style.padding = padding;
      plus.insertAdjacentElement('afterend', etoile);
    });
  }

  function listeQuick() {
    const n = Math.max(1, Math.min(10, reglages.quickNombre | 0 || 4));
    const l = Array.isArray(reglages.quickListe) ? reglages.quickListe.slice(0, n) : [];
    while (l.length < n) l.push(null);
    return l;
  }
  function poserQuick(i, url) {
    const l = Array.isArray(reglages.quickListe) ? reglages.quickListe.slice() : [];
    while (l.length <= i) l.push(null);
    l[i] = url || null;
    reglages.quickListe = l;
    enregistrer();
    majQuickReacs();
  }
  function postDuMenu(menuSite) { return postReel(menuSite.closest('.post-container')); }
  async function reagirQuick(post, url) {
    if (!post) return;
    if (fenetreFavPost && fenetreFavPost.post === post) fermerFavorisPost();
    notifier('Ajout de la réaction…');
    const ok = await reagirAvec(post, url);
    notifier(ok ? 'Réaction ajoutée' : 'La réaction n\'a pas pu être ajoutée toute seule : la fenêtre du site est ouverte (lien copié).', !ok);
  }

  function choisirPourSlot(post, i) {
    if (!post) return;
    const smiley = duPost(post, '.reaction-list-btn');
    if (!(fenetreFavPost && fenetreFavPost.post === post)) ouvrirFavorisPost(post, smiley || post);
    const f = fenetreFavPost;
    if (!f) return;

    viserSlot(f.barre, i);
  }

  function viserSlot(barreFav, i) {
    barreFav._rpSlotQuick = barreFav._rpSlotQuick === i ? null : i;
    majSlotsEntete();
  }

  function remplirSlotVise(barreFav, url) {
    if (!barreFav || barreFav._rpSlotQuick == null) return false;
    const i = barreFav._rpSlotQuick;
    barreFav._rpSlotQuick = null;
    poserQuick(i, url);
    return true;
  }
  function quickDansBarre(barreFav) {
    if (!reglages.quickReacs) return false;
    if (barreFav._rpPost) return !!reglages.quickFenetre;
    return !!barreFav._rpZone && !!reglages.quickEditeur;
  }
  function lienPourSlot(dt) {
    if (depotEnCours && depotEnCours.url) return depotEnCours.url;
    if (stickerSousDossierGlisse) return stickerSousDossierGlisse;
    const l = dt ? lienDepuisDepot(dt) : '';
    return l && hebergeAffichable(normaliserLien(l)) ? normaliserLien(l) : '';
  }

  function tailleSlotQuick() { return Math.max(16, Math.min(TAILLE_STICKER_MAX, reglages.tailleSticker | 0 || 32)) + 4; }
  let slotGlisse = -1;
  var stickerSousDossierGlisse = null;
  function creerSlotQuick(trouverPost, i, url, taille, avecGlisser, barre) {
    const zoneEd = barre && barre._rpZone;

    const gestionSeule = !!barre;
    const s = document.createElement('button');
    s.type = 'button';
    s.setAttribute('data-rp-quick-slot', i);
    s.style.cssText = 'flex:none;width:' + taille + 'px;height:' + taille + 'px;padding:0;margin:0 1px;box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;' +
      'border-radius:6px;cursor:pointer;background:none;color:inherit;' + (url ? 'border:1px solid transparent;' : 'border:1px dashed rgba(127,127,127,.55);opacity:.7;');
    if (url) {
      const im = document.createElement('img');
      im.src = url;
      im.alt = '';
      im.draggable = false;
      im.style.cssText = 'max-width:' + (taille - 4) + 'px;max-height:' + (taille - 4) + 'px;object-fit:contain;pointer-events:none;';
      s.appendChild(im);
      s.title = 'Quick Réact ' + (i + 1) + ' : ' + nomSticker(url) + '\n' + (gestionSeule ? 'Clic : le remplacer (puis clic sur un sticker) · pour réagir : slots du menu sous un post' : 'Clic : réagir') + ' · clic droit : changer / vider · glisse un sticker ici pour le remplacer';
    } else {
      s.textContent = '+';
      s.style.fontSize = Math.round(taille * 0.55) + 'px';
      s.title = 'Quick Réact ' + (i + 1) + ' (vide)\nClic : choisir dans les Favoris · ou glisse un sticker des Favoris ici';
    }
    s.addEventListener('mouseenter', function () { s.style.background = 'rgba(127,127,127,.2)'; });
    s.addEventListener('mouseleave', function () { s.style.background = 'none'; });
    ['mousedown', 'pointerdown', 'mouseup', 'pointerup'].forEach(function (t) {
      s.addEventListener(t, function (e) { if (e.button === 0) e.stopPropagation(); });
    });
    s.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      const u = listeQuick()[i];
      if (barre && barre._rpSlotQuick != null) {
        if (!u || barre._rpSlotQuick === i) { viserSlot(barre, i); return; }
        barre._rpSlotQuick = null;
        majSlotsEntete();
      }
      if (u && gestionSeule) { viserSlot(barre, i); return; }
      if (u) { if (zoneEd) insererDansMessage(zoneEd, u); else reagirQuick(trouverPost(), u); return; }
      if (barre) viserSlot(barre, i); else choisirPourSlot(trouverPost(), i);
    });
    s.addEventListener('contextmenu', function (e) {
      e.preventDefault();
      e.stopPropagation();
      const u = listeQuick()[i];
      menuContextuel(e, [
        { titre: '⚡ Quick Réact ' + (i + 1) + (u ? ' · ' + nomSticker(u) : ' (vide)') },
        'sep',
        { texte: u ? 'Changer…' : 'Choisir…', action: function () { if (barre) { barre._rpSlotQuick = null; viserSlot(barre, i); } else choisirPourSlot(trouverPost(), i); } },
        { texte: 'Vider le slot', danger: true, desactive: !u, action: function () { poserQuick(i, null); } },
      ]);
    });

    if (!avecGlisser) return s;
    if (url) {
      s.draggable = true;
      s.addEventListener('dragstart', function (e) {
        slotGlisse = i;

        const lien = listeQuick()[i];
        try {
          e.dataTransfer.setData('text/rp-quick-slot', String(i));
          if (lien) { e.dataTransfer.setData('text/plain', lien); if (/^https?:/i.test(lien)) e.dataTransfer.setData('text/uri-list', lien); }
          e.dataTransfer.effectAllowed = 'copyMove';
        } catch (er) {  }
        if (lien) depotEnCours = { url: lien, zone: (barre && barre._rpZone) || null };
      });
      s.addEventListener('dragend', function () { setTimeout(function () { slotGlisse = -1; depotEnCours = null; }, 0); });
    }
    function survol(e) {
      const okType = e.dataTransfer && Array.from(e.dataTransfer.types || []).some(function (t) { return t === 'text/uri-list' || t === 'text/plain'; });
      if (slotGlisse < 0 && !depotEnCours && !stickerSousDossierGlisse && !okType) return;
      e.preventDefault();
      e.stopPropagation();
      e.dataTransfer.dropEffect = slotGlisse >= 0 ? 'move' : 'copy';
      s.style.outline = '2px dashed var(--button-color,#5C7CAD)';
      s.style.outlineOffset = '1px';
    }
    s.addEventListener('dragenter', survol);
    s.addEventListener('dragover', survol);
    s.addEventListener('dragleave', function () { s.style.outline = ''; });
    s.addEventListener('drop', function (e) {
      s.style.outline = '';
      e.preventDefault();
      e.stopPropagation();
      if (slotGlisse >= 0) {
        const a = slotGlisse;
        slotGlisse = -1;
        if (a === i) return;
        const l = listeQuick();
        const x = l[a]; l[a] = l[i]; l[i] = x;
        reglages.quickListe = l;
        enregistrer();
        majQuickReacs();
        return;
      }
      const u = lienPourSlot(e.dataTransfer);
      if (!u) { notifier('Quick Réacts : seulement un sticker des Favoris ou une image Noelshack / Risibank.', true); return; }
      poserQuick(i, u);
    });
    return s;
  }
  function installerQuickReacs(menuSite, plus) {
    let boite = menuSite.querySelector('[data-rp-quick]');
    if (!reglages.quickReacs || !reglages.quickMenuSite) { if (boite) boite.remove(); return; }
    const liste = listeQuick();
    const taille = tailleSlotQuick();
    const sig = taille + '#' + liste.join('|');
    if (boite && boite.getAttribute('data-rp-quick') === sig) return;
    if (!boite) {
      boite = document.createElement('span');
      boite.style.cssText = 'display:inline-flex;align-items:center;gap:2px;flex:none;';

      const emoji = reactionsSiteDuMenu(menuSite)[0];
      if (emoji && emoji.parentElement) emoji.parentElement.insertBefore(boite, emoji);
      else plus.parentElement.insertBefore(boite, plus);
    }
    boite.setAttribute('data-rp-quick', sig);
    boite.textContent = '';
    liste.forEach(function (u, i) { boite.appendChild(creerSlotQuick(function () { return postDuMenu(menuSite); }, i, u, taille)); });
  }

  function remplirSlotsEntete(slots, barreFav) {
    const vise = barreFav._rpSlotQuick;
    slots.textContent = '';
    listeQuick().forEach(function (u, i) {
      const s = creerSlotQuick(function () { return barreFav._rpPost; }, i, u, tailleSlotQuick(), true, barreFav);
      if (vise === i) {
        s.setAttribute('data-rp-quick-vise', '');
        s.style.outline = '2px solid var(--button-color,#5C7CAD)';
        s.style.outlineOffset = '1px';
        s.style.opacity = '1';
        s.title = 'Slot ' + (i + 1) + ' : clique sur un sticker pour le mettre ici (re-clic sur le slot : annuler)';
      }
      slots.appendChild(s);
    });
  }
  function majSlotsEntete() {
    document.querySelectorAll('[' + ATTR_BARRE_FAV + ']').forEach(function (b) {
      if (!b.isConnected || (!b._rpPost && !b._rpZone)) return;
      const slots = b.querySelector('[data-rp-quick-fenetre]');
      if (!!slots !== quickDansBarre(b)) { dessinerBarreFavoris(b); return; }
      if (slots) remplirSlotsEntete(slots, b);
    });
  }
  function installerQuickFenetre() { majSlotsEntete(); }
  function majQuickReacs() {
    document.querySelectorAll('.reaction-menu [data-rp-quick]').forEach(function (b) { b.setAttribute('data-rp-quick', '~'); });
    installerIconesPosts();
    installerQuickFenetre();
    traiterReactions();
  }

  function installerIcone() {
    installerIconesPosts();
    appliquerVisibiliteRB();
    document.querySelectorAll(SEL_ZONES).forEach(function (zone) {
      if (!zone._rpSuivi) {
        zone._rpSuivi = true;
        zone.addEventListener('blur', function () {
          zone._rpCurseur = { debut: zone.selectionStart, fin: zone.selectionEnd };
        });

        zone.addEventListener('eco-curseur', function () {
          zone._rpCurseur = { debut: zone.selectionStart, fin: zone.selectionEnd };
        });
      }
      if (zone.closest('[data-rp-panneau], [' + ATTR_BARRE_FAV + ']')) return;
      const barre = barreOutils(zone);
      if (!barre || barre.querySelector('[' + ATTR_ICONE + ']')) return;

      const rb = Array.from(barre.querySelectorAll('*')).find(function (el) {
        return (el.textContent || '').trim() === 'RB' || /risi/i.test((el.getAttribute('title') || '') + (el.getAttribute('alt') || ''));
      });
      let apres = rb;
      while (apres && apres.parentElement !== barre) apres = apres.parentElement;
      zone._rpBoutonRB = apres || null;

      zone._rpBoutonHap = apres && apres.previousElementSibling && !apres.previousElementSibling.hasAttribute(ATTR_ICONE) ? apres.previousElementSibling : null;
      if (apres && reglages.rbBarreOutils === false) apres.style.display = 'none';
      if (zone._rpBoutonHap && reglages.hapBarreOutils === false) zone._rpBoutonHap.style.display = 'none';
      copierSurvol(apres || barre.querySelector('button'), ATTR_ICONE);

      const etoile = creerIcone('favoris', function () { basculerBarreFavoris(zone); });
      zone._rpEtoile = etoile;
      etoile.title = 'Favoris : afficher / masquer la barre\nGlisse une image ici pour ouvrir la barre (et l\'y lâcher pour l\'ajouter)';
      activerGlisserSurEtoile(etoile, zone);
      if (apres) barre.insertBefore(etoile, apres.nextSibling);
      else barre.appendChild(etoile);

      if (apres) {
        const hap = apres.previousElementSibling;
        barre.addEventListener('click', function (e) {
          if (clicInterne) return;
          let enfant = e.target;
          while (enfant && enfant.parentElement !== barre) enfant = enfant.parentElement;
          if (enfant && (enfant === apres || enfant === hap)) {
            zone._rpDernierSelecteur = enfant;
            fermerPanneaux(zone);
          }
        }, true);
      }
    });
  }

  const styleBoutonReglages = document.createElement('style');
  document.head.appendChild(styleBoutonReglages);
  function appliquerVisibiliteRB() {

    const css = '[' + ATTR_ICONE + ']:not([data-rp-etoile]){display:none!important;}';
    if (styleBoutonReglages.textContent !== css) styleBoutonReglages.textContent = css;
    document.querySelectorAll(SEL_ZONES).forEach(function (zone) {
      const rb = zone._rpBoutonRB;
      if (rb && rb.isConnected) rb.style.display = reglages.rbBarreOutils === false ? 'none' : '';
      const hap = zone._rpBoutonHap;
      if (hap && hap.isConnected) hap.style.display = reglages.hapBarreOutils === false ? 'none' : '';
    });
  }
  let rbDepuisBarre = 0;
  function allumer(b, oui) {
    if (!b) return;
    b.style.background = oui ? 'var(--button-color,#5C7CAD)' : 'none';
    b.style.borderColor = oui ? 'var(--button-color,#5C7CAD)' : '#5A5F66';
    b.style.color = oui ? 'var(--button-text-color,#fff)' : 'inherit';
    b.style.opacity = oui ? '1' : '.85';
    b._rpAllume = oui;
  }

  function majBoutonsSelecteurs() {
    document.querySelectorAll('[' + ATTR_BARRE_FAV + ']').forEach(function (barre) {
      const m = modeBarre(barre);
      barre.querySelectorAll('[data-rp-rb]').forEach(function (b) { if (b._rpAllume !== (m === 'rb')) allumer(b, m === 'rb'); });
      barre.querySelectorAll('[data-rp-hap]').forEach(function (b) { if (b._rpAllume !== (m === 'hap')) allumer(b, m === 'hap'); });
    });
  }

  function basculerSelecteurDuSite(zone, rb) {
    if (!rb || !rb.isConnected) return false;
    const cible = rb.matches('button, [role="button"]') ? rb : (rb.querySelector('button, img, svg') || rb);
    zone._rpDernierSelecteur = rb;
    zone._rpBasculeA = Date.now();
    rbDepuisBarre = Date.now();
    clicInterne = true;
    try { cible.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true })); } finally { clicInterne = false; }
    [0, 120, 400].forEach(function (d) { setTimeout(majBoutonsSelecteurs, d); });
    return true;
  }

  const selecteursVus = new WeakSet();

  const CLE_SMILEYS = 'nanachan-reactions-plus-smileys';
  let smileysSite = { images: [], emojis: [] };
  try { const c = JSON.parse(localStorage.getItem(CLE_SMILEYS) || 'null'); if (c && Array.isArray(c.images)) smileysSite = c; } catch (e) {  }
  function selecteurEstRisibank(el) { return /risibank/i.test(el.textContent || '') || !!el.querySelector('img[src*="risibank"]'); }
  function lireSelecteurSmileys(el) {
    if (!el.isConnected || selecteurEstRisibank(el)) return false;
    let change = false;
    const vus = new Set(smileysSite.images.map(function (x) { return x.src; }));
    el.querySelectorAll('img').forEach(function (im) {
      let src = im.currentSrc || im.getAttribute('src') || '';
      if (!src || /^data:/i.test(src)) return;
      try { src = new URL(src, location.href).href; } catch (e) { return; }
      if (vus.has(src)) return;
      vus.add(src);
      smileysSite.images.push({ src: src, nom: (im.getAttribute('alt') || im.getAttribute('title') || '').trim() });
      change = true;
    });
    el.querySelectorAll('*').forEach(function (x) {
      if (x.children.length) return;
      const t = (x.textContent || '').trim();
      if (t && t.length <= 16 && estEmoji(t) && smileysSite.emojis.indexOf(t) === -1) { smileysSite.emojis.push(t); change = true; }
    });
    if (change) {
      smileysSite.date = Date.now();
      try { localStorage.setItem(CLE_SMILEYS, JSON.stringify(smileysSite)); } catch (e) {  }

      if (fenetreFavPost && modeBarre(fenetreFavPost.barre) === 'hap' && !zoneSourceSmileys(fenetreFavPost.barre)) dessinerBarreFavoris(fenetreFavPost.barre);
    }
    return change;
  }
  function suivreSelecteurSmileys(el) {
    [300, 1200].forEach(function (d) { setTimeout(function () { lireSelecteurSmileys(el); }, d); });
    el.addEventListener('click', function () { setTimeout(function () { lireSelecteurSmileys(el); }, 300); }, true);
  }

  let lectureSmileysEnCours = false;
  function chargerSmileysDuSite(fin) {
    if (lectureSmileysEnCours) return;
    const zone = Array.from(document.querySelectorAll(SEL_ZONES)).find(function (z) { return z._rpBoutonHap && z._rpBoutonHap.isConnected; });
    if (!zone) { fin(false); return; }
    lectureSmileysEnCours = true;
    const avant = new Set(document.querySelectorAll('[class*="picker"]'));
    basculerSelecteurDuSite(zone, zone._rpBoutonHap);
    const debut = Date.now();
    (function guetter() {
      const sel = Array.from(document.querySelectorAll('[class*="picker"]')).find(function (el) {
        return el.offsetParent !== null && !selecteurEstRisibank(el) && (!avant.has(el) || el.querySelector('img'));
      });
      if (sel && (sel.querySelector('img') || Date.now() - debut > 1500)) {
        setTimeout(function () {
          lireSelecteurSmileys(sel);
          basculerSelecteurDuSite(zone, zone._rpBoutonHap);
          lectureSmileysEnCours = false;
          fin(true);
        }, 300);
        return;
      }
      if (Date.now() - debut > 3000) { lectureSmileysEnCours = false; fin(false); return; }
      setTimeout(guetter, 100);
    })();
  }

  function lienTwemoji(emoji) {
    const cps = Array.from(emoji).map(function (c) { return c.codePointAt(0).toString(16); });
    const avecZwj = cps.indexOf('200d') !== -1;
    return 'https://cdn.jsdelivr.net/gh/jdecked/twemoji@latest/assets/72x72/' + cps.filter(function (h) { return avecZwj || h !== 'fe0f'; }).join('-') + '.png';
  }
  function reagirSmileyDepuisFenetre(url) {
    const f = fenetreFavPost;
    if (!f) return;
    const post = f.post;
    fermerFavorisPost();
    reagirParDepot(post, url, null);
  }
  function panneauSmileys(barreFav) {
    const p = document.createElement('div');
    p.setAttribute('data-rp-smileys', '');
    p.style.cssText = 'max-height:260px;overflow-y:auto;scrollbar-width:none;display:flex;flex-direction:column;gap:8px;';
    p.addEventListener('scroll', function () { majFonduNav(p); }, { passive: true });
    requestAnimationFrame(function () { majFonduNav(p); });
    function titre(t) {
      const d = document.createElement('div');
      d.textContent = t;
      d.style.cssText = 'font-size:11px;opacity:.55;';
      return d;
    }
    function grille() {
      const g = document.createElement('div');
      g.style.cssText = 'display:flex;flex-wrap:wrap;gap:4px;';
      return g;
    }
    function caseSmiley(contenu, titreCase, action) {
      const c = document.createElement('button');
      c.type = 'button';
      c.title = titreCase;
      c.style.cssText = 'width:40px;height:40px;padding:2px;border:1px solid transparent;border-radius:6px;background:rgba(127,127,127,.12);cursor:pointer;' +
        'display:flex;align-items:center;justify-content:center;font-size:24px;line-height:1;color:inherit;';
      c.appendChild(contenu);
      c.addEventListener('mouseenter', function () { c.style.borderColor = 'var(--button-color,#5C7CAD)'; });
      c.addEventListener('mouseleave', function () { c.style.borderColor = 'transparent'; });
      c.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); action(); });
      return c;
    }
    const vide = !smileysSite.images.length && !smileysSite.emojis.length;
    if (vide) {
      const msg = titre(lectureSmileysEnCours ? 'Lecture des smileys du site…' : 'Aucun smiley connu pour l\'instant : ouvre une fois le sélecteur de smileys de l\'éditeur (ou réessaie).');
      p.appendChild(msg);
      if (!lectureSmileysEnCours) {
        msg.textContent = 'Lecture des smileys du site…';
        chargerSmileysDuSite(function (ok) {
          if (!ok) msg.textContent = 'Smileys introuvables ici : ouvre une fois le sélecteur de smileys de l\'éditeur, ils seront retenus.';
          else if (barreFav.isConnected) dessinerBarreFavoris(barreFav);
        });
      }
      return p;
    }
    p.appendChild(titre('Clic : réagir avec (envoyé en image, visible par tous)'));
    if (smileysSite.images.length) {
      const g = grille();
      smileysSite.images.forEach(function (x) {
        const im = document.createElement('img');
        im.src = x.src;
        im.alt = '';
        im.draggable = false;
        im.style.cssText = 'max-width:34px;max-height:34px;object-fit:contain;pointer-events:none;';
        g.appendChild(caseSmiley(im, (x.nom || 'smiley') + ' — réagir avec', function () { reagirSmileyDepuisFenetre(x.src); }));
      });
      p.appendChild(g);
    }
    if (smileysSite.emojis.length) {
      const g = grille();
      smileysSite.emojis.forEach(function (e) {
        const sp = document.createElement('span');
        sp.textContent = e;
        sp.style.pointerEvents = 'none';
        g.appendChild(caseSmiley(sp, e + ' — réagir avec (converti en image)', function () { reagirSmileyDepuisFenetre(lienTwemoji(e)); }));
      });
      p.appendChild(g);
    }
    return p;
  }

  const HAUTEUR_PANNEAU = 260;
  function modeBarre(b) { return (b && b._rpMode) || 'favoris'; }
  function barresEnMode(m) {
    return Array.from(document.querySelectorAll('[' + ATTR_BARRE_FAV + ']')).filter(function (b) { return modeBarre(b) === m; });
  }
  function editeurAvec(cle) {
    return Array.from(document.querySelectorAll(SEL_ZONES)).find(function (z) { return z[cle] && z[cle].isConnected; }) || null;
  }
  function changerModeBarre(barreFav, m) {
    if (modeBarre(barreFav) === m) m = 'favoris';
    barreFav._rpMode = m;
    if (barreFav._rpPost) modePanneauPost = m;
    if (sousDossierOuvert && barreFav.contains(sousDossierOuvert.el)) fermerSousDossier();
    dessinerBarreFavoris(barreFav);
    libererSourceSiInutile();
  }
