    [l1, l2].forEach(function (l) { l.style.cssText = 'font-size:11px;opacity:.6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;'; });
    const dossier = loc.dossier ? (loc.dossier.recents ? '🕘 ' : '📁 ') + loc.dossier.nom + (loc.groupe ? ' › ' + loc.groupe.nom : '') : '';
    if (estGroupe(item)) {
      nom.textContent = '📁 ' + item.nom;
      l1.textContent = 'Sous-dossier · ' + item.stickers.length + ' sticker' + (item.stickers.length > 1 ? 's' : '');
      l2.textContent = 'Dans ' + dossier;
      if (item.stickers[0]) vignette.style.backgroundImage = 'url("' + String(item.stickers[0]).replace(/"/g, '%22') + '")';
    } else {
      const perso = nomPerso(item);
      nom.textContent = nomSticker(item);
      nom.title = perso ? perso + ' (nom d\'origine : ' + nomOrigine(item) + ')' : nomOrigine(item);
      const ext = (String(item).split(/[?#]/)[0].match(/\.([a-z0-9]{2,5})$/i) || [])[1];
      const base = [hoteSticker(item), ext ? ext.toUpperCase() : null].filter(Boolean);
      l1.textContent = base.join(' · ');
      l2.textContent = dossier;
      if (perso) {
        const lo = document.createElement('div');
        lo.textContent = 'Nom d\'origine : ' + nomOrigine(item);
        lo.style.cssText = 'font-size:11px;opacity:.6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';
        texte.appendChild(nom);
        texte.appendChild(lo);
      }
      vignette.style.backgroundImage = 'url("' + String(item).replace(/"/g, '%22') + '")';

      const im = new Image();
      im.onload = function () {
        if (!h.isConnected && !h.parentNode) return;
        base.push(im.naturalWidth + '×' + im.naturalHeight);
        l1.textContent = base.join(' · ');
      };
      im.src = item;
      try {
        fetch(item, { method: 'HEAD', credentials: 'omit' }).then(function (r) {
          const n = +r.headers.get('content-length');
          if (n > 0) { base.push(n < 1024 ? n + ' o' : n < 1024 * 1024 ? Math.round(n / 1024) + ' Ko' : (n / 1024 / 1024).toFixed(1).replace('.', ',') + ' Mo'); l1.textContent = base.join(' · '); }
        }).catch(function () {  });
      } catch (err) {  }
      l1.title = item;
    }
    if (!nom.parentNode) texte.appendChild(nom);
    texte.appendChild(l1);
    if (l2.textContent) texte.appendChild(l2);
    h.appendChild(vignette);
    h.appendChild(texte);
