    ok.style.cssText = 'background:var(--button-color,#5C7CAD);color:var(--button-text-color,#fff);border:none;border-radius:4px;padding:4px 10px;cursor:pointer;font-size:12px;';
    ligne.appendChild(champ);
    ligne.appendChild(ok);
    const origine = document.createElement('div');
    origine.style.cssText = 'display:flex;align-items:center;gap:6px;margin-top:6px;font-size:11px;color:#8A8D91;';
    const texteOrigine = document.createElement('span');
