      'border:1px solid #444850;box-shadow:0 8px 24px rgba(0,0,0,.55);color:#E8E8E8;font-size:12px;font-weight:400;';
    const ligne = document.createElement('div');
    ligne.style.cssText = 'display:flex;gap:6px;';
