        const extR = ((fichier.match(/\.([a-z0-9]+)$/i) || [])[1] || '').toLowerCase();
        const versPng = /^(jpe?g|bmp)$/.test(extR)
          ? ezgifOutil((extR === 'jpeg' ? 'jpg' : extR) + '-to-png', fichier, {}, EXTS_IMAGE).then(function (o) { fichier = o.fichier; lien = o.lien; ezgifNoter('↳ calque « ' + (c.nom || '') + ' » : ' + extR.toUpperCase() + ' → PNG (coins transparents)'); }, function (e) { ezgifNoter('↳ calque : conversion en PNG impossible (' + ((e && e.message) || e) + ') : coins blancs possibles'); })
          : Promise.resolve();

