  async function reponseNotifications(url) {
    if (!d.reglages.notifications || !quelquUnMasque()) return null;
    const r = await fetch(url, { credentials: 'include', headers: entetes(false) });
    if (!r.ok) return null;
    const j = await r.json();
    const garder = function (n) { return !(n && n.sender && n.sender.username && postsMasques(n.sender.username) && !(entree(n.sender.username) || {}).filtre); };
    if (Array.isArray(j)) return JSON.stringify(j.filter(garder));
    if (j && Array.isArray(j.results)) {
      const avant = j.results.length;
      j.results = j.results.filter(garder);
      if (typeof j.count === 'number') j.count -= avant - j.results.length;
    }
    return JSON.stringify(j);
  }
  async function reponseNonLus() {
    const cb = lireCorbeilleMP();
    if (!Object.keys(cb.c).length && (d.reglages.mp === 'normal' || !quelquUnMasque())) return null;
    if (nonLus && Date.now() - nonLus.t < 20000) return JSON.stringify({ unread: nonLus.n });
    let n = 0;
    for (let page = 1; page <= 5; page++) {
      const r = await fetch('/nanachannel/mp/conversations/?page=' + page, { credentials: 'include', headers: entetes(false) });
      if (!r.ok) { if (page === 1) return null; break; }
      const j = await r.json();
      const res = (j && j.results) || [];
      res.forEach(function (c) {
        const p = c && c.participant && c.participant.username;
        if (c && c.unread_count && !(p && enCorbeilleMP(p, cb))) n += c.unread_count;
      });
      if (!j.next || !res.length) break;
    }
    nonLus = { t: Date.now(), n: n };
    return JSON.stringify({ unread: n });
  }

