    l._vpLoc = { d: d, s: -1, i: i, groupe: true };
    l.append(el('span', { classe: 'vp-poignee', title: 'Glisser pour déplacer' }, '⠿'), el('span', { style: 'width:24px;text-align:center' }, '📁'));
    const n = bouton(G.nom, 'Ouvrir le sous-dossier', function () { barre._vpS = i; dessinerCorps(barre); }, { classe: 'vp-nomi' });
    l.append(n, el('span', { classe: 'vp-meta' }, G.items.length + ' Vocaroo'));
    l.appendChild(bouton('⋮', 'Options du sous-dossier', function (e, b) { menuSous(b, barre, d, i); }, { classe: 'vp-x' }));
    l.addEventListener('contextmenu', function (e) { e.preventDefault(); menuSous({ x: e.clientX, y: e.clientY }, barre, d, i); });
    activerGlisserLigne(l, barre);
