  function calculerVague(url) {
    return fetch(url).then(function (r) { return r.arrayBuffer(); }).then(function (buf) {
      if (buf.byteLength > 30e6) throw new Error('trop long');
      const AC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
      if (!AC) throw new Error('pas de décodage audio');
      const ctx = new AC(1, 1, 22050);
      return new Promise(function (ok, ko) {
        const p = ctx.decodeAudioData(buf, ok, ko);
        if (p && p.then) p.then(ok, ko);
      });
    }).then(function (audio) {
      const d = audio.getChannelData(0);
      const taille = Math.max(1, Math.floor(d.length / N_VAGUE));
      const pas = Math.max(1, Math.floor(taille / 400));
      const pics = new Float32Array(N_VAGUE);
      let max = 0;
      for (let i = 0; i < N_VAGUE; i++) {
        let m = 0;
        for (let j = i * taille, f = Math.min(d.length, (i + 1) * taille); j < f; j += pas) { const v = Math.abs(d[j]); if (v > m) m = v; }
        pics[i] = m;
        if (m > max) max = m;
      }
      const u8 = new Uint8Array(N_VAGUE);
      for (let i = 0; i < N_VAGUE; i++) u8[i] = Math.round(Math.sqrt(pics[i] / (max || 1)) * 255);
      return u8;
    });
  }

