  const ECO_MARQUES_ATTR = /^data-(eco|rp|up|np|pp|lp|cp|ip|mp|mpp|sbp|tp|ar|citation|image-hover|liens-plus|uploads-plus|reactions-plus|shitbox-plus|messages-plus|mp-plus|bl|fp|sdp|vp|nav)(-|$)/;
  const ECO_MARQUES_CLASSE = /(^|\s)(eco-|sbp-|nana-|auto-refresh|lp-|cp-|rp-|tp-|np-|up-|mpp-|bl-|fp-|sdp-|vp-|nanachan-)/;

